from ta_emss.utilities.trs import handler


class EmssimCommand(handler.DataHandler):
    def __init__(self, method=None, timeout=60, rpc_connection_name='localRPC'):
        super(EmssimCommand, self).__init__(method, timeout, rpc_connection_name)
        self.failure_reason = ''
        self._data = []
        self._proxy_events = []

    def get_data(self):
        return self._data

    def get_proxy_events(self):
        return self._proxy_events

    def on_prepare_run(self, *run_params, **run_kwparams):
        ''' EMSSIM commands return dictionary as their result'''
        super(EmssimCommand, self).on_prepare_run(*run_params, **run_kwparams)
        self._ret = {}
        self._data = []
        self._proxy_events = []

    def on_new_data(self, **data):
        ''' EMSSIM data incomming over RPC has a form (some fields are optional):
        { 'status': 'started'|'running'|'end_of_command'|'stopped',
          'data': {
                    'msg': 'any text',
                    'status': 'STARTED'|'SUCCESS'|,
                    'timeout': <updated timeout of command>,
                  },
        }
        This generic handler processes 'status' key
        and returns content of 'data' key

        Derived classes on_new_data() should call:
        data = super(XXXcmd, self).on_new_data(**data)
        and they should build self._ret dictionary from data returned by base class
        WARNING: the last 'stopped' or 'end_of_command' message processing cannot be included in _ret
        as the command status is known eariler to parent data handler finishing the processing,
        thus avoid unconditional assign of the whole data to _ret directly as self._ret = data.
        '''

        if 'type' in data:
            if data['type'] == 'proxy' and 'data' in data:
                self._proxy_events.append(data['data'])
            return {}

        if 'data' in data:
            self._data.append(data['data'])

        if not isinstance(data, dict):
            print("WARNING: Command data not a dictionary - will not be processed: %s" % data['data'])
            return {}

        self._process_cmd_state(data)
        self._process_cmd_timeout(data)

#       print("on_new_data:             data = %s" % data)
#       print("              self._run_state = %s" % self._run_state)
#       print("                  self.status = %s" % self.status)
#       print("                    self._ret = %s" % self._ret)

        if 'data' in data:
            self._set_json_admin_data(data['data'])
            self._set_full_scf_data(data['data'])
            return data['data']
        else:
            return {}

    def _set_json_admin_data(self, data):
        if 'msg' in data and data['msg'] == 'JSON admin plan generated':
            if 'file_path' in data:
                self._ret['json_admin_file_path'] = data['file_path']
            if 'plan_id' in data:
                self._ret['json_admin_plan_id'] = data['plan_id']

    def _set_full_scf_data(self, data):
        if 'msg' in data and data['msg'] == 'Full SCF plan generated':
            if 'file_path' in data:
                self._ret['full_scf_file_path'] = data['file_path']
            if 'plan_id' in data:
                self._ret['full_scf_plan_id'] = data['plan_id']

    def _process_cmd_state(self, data):
        if data['status'] == 'running':
            self._run_state = handler.RunState.running
        elif data['status'] == 'end_of_command' or data['status'] == 'stopped':
            if data['data']['result']:
                self.status = handler.SUCCESS
            else:
                self.status = handler.FAILURE
        elif data['status'] == 'error':
            self.status = handler.FAILURE
            self.failure_reason = 'unknown'
            if 'msg' in data['data']:
                self.failure_reason = data['data']['msg']
        else:
            print("Unknown EMSSIM runing state: %s" % data['status'])
            self.status = handler.FAILURE

    def _process_cmd_timeout(self, data):
        if ('data' in data) and ('timeout' in data['data']):
            # Add 5 seconds to emssim timeout to allow emssim command fail first
            new_timeout = float(data['data']['timeout']) + 5.0
            self.set_timeout(new_timeout)

    def parse_table_with_unique_key_to_dictionary(self, table, unique_key):
        '''utility method to be used by derived commands'''
        parsed_table = {}
        for row in table:
            if (row):
                parsed_table[row[unique_key]] = row
        return parsed_table
